import{_ as t,a,o as n,a4 as i}from"./chunks/framework.-FZumj2l.js";const h=JSON.parse('{"title":"Events","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-api/admin/marketing/communications/events/index.md","filePath":"api/rest-api/admin/marketing/communications/events/index.md","lastUpdated":1784902076000}'),o={name:"api/rest-api/admin/marketing/communications/events/index.md"};function s(d,e,r,m,c,p){return n(),a("div",null,e[0]||(e[0]=[i('<h1 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h1><p>A <strong>marketing event</strong> is a dated entry that anchors campaigns — for example a sale kickoff date. It mirrors the admin <strong>Marketing → Communications → Events</strong> screen.</p><h2 id="how-an-event-works" tabindex="-1">How an event works <a class="header-anchor" href="#how-an-event-works" aria-label="Permalink to &quot;How an event works&quot;">​</a></h2><p>An event is intentionally simple: a <code>name</code>, a <code>description</code>, and a <code>date</code>. Its purpose is to give campaigns a fixed calendar anchor.</p><ul><li><strong><code>name</code></strong> — the event label shown in the admin list.</li><li><strong><code>description</code></strong> — free-text notes about what the event is for.</li><li><strong><code>date</code></strong> — the calendar date (<code>YYYY-MM-DD</code>) the event lands on.</li></ul><p><strong>Relation to Campaigns.</strong> A campaign may reference an event so a scheduled send lines up with the event&#39;s date. The event itself sends nothing — it only marks the date a campaign can be timed against.</p><p>There is no mass-delete for events — the admin UI exposes per-row delete only.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/marketing/communications/events-list.html">List</a></td><td><code>GET /api/admin/marketing/events</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/communications/events-detail.html">Detail</a></td><td><code>GET /api/admin/marketing/events/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/communications/events-create.html">Create</a></td><td><code>POST /api/admin/marketing/events</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/communications/events-update.html">Update</a></td><td><code>PUT /api/admin/marketing/events/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/communications/events-delete.html">Delete</a></td><td><code>DELETE /api/admin/marketing/events/{id}</code></td></tr></tbody></table><p>All Events endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',10)]))}const g=t(o,[["render",s]]);export{h as __pageData,g as default};
